```javascript
function checkMark() {
  const v = document.getElementById("mark").value;
  const msg = document.getElementById("msg");
  if (v == "") msg.textContent = "Enter a mark";
  else if (isNaN(v) || Number(v) < 0 || Number(v) > 100) msg.textContent = "Mark must be 0–100";
  else msg.textContent = "Accepted";
}
```

